import { topics, sampleQuestions } from './data.js';
import { preparedNotes } from './notes.js';
import { typesetNotes, validateMathText } from './math.js';
import { mergeCatalogue, resourceKey, storePreviewPdf, loadPreviewPdf, validatePdf } from './library.js';

const CONFIG = window.NAMMATH_CONFIG || {};
const backendConfigured = Boolean(CONFIG.supabaseUrl && CONFIG.publishableKey);
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const escapeHtml = (s) => String(s ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const DEMO_KEY = 'nammath_as_demo_progress_v2';
const LIBRARY_KEY = 'nammath_as_demo_library_v3';
const NOTES_KEY = 'nammath_as_demo_notes_v3';
function readLocal(key, fallback){try{return JSON.parse(localStorage.getItem(key) || 'null') || fallback;}catch{return fallback;}}
function writeLocal(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{return false;}}
let previewPdfUrl = null;
let demoProgress = {};
try { demoProgress=JSON.parse(localStorage.getItem(DEMO_KEY)||'{}') || {}; } catch { demoProgress={}; }
const state = {bankReady:false,view:'home',topicFilter:'all',search:'',topic:null,mode:'topic',questions:[],index:0,selected:-1,graded:false,gradeResult:null,attempts:backendConfigured?{}:demoProgress,premium:false,expiry:null,user:null,supabase:null,authMode:'signin',timerEnd:null,memo:null,library:backendConfigured?[]:readLocal(LIBRARY_KEY,[]),notes:{...preparedNotes,...(backendConfigured?{}:readLocal(NOTES_KEY,{}))},isAdmin:!backendConfigured,contentCategory:'past',notesPaper:'1',selectedNote:'m1-equations',libraryLoading:false};
let examClock;
const main=$('#main');
const navMap={home:'Dashboard',topics:'Explore Topics',papers:'Mini Mocks',past:'Past Papers',regional:'Regional Mocks',notes:'Study Notes',studio:'Content Studio',progress:'My Progress',premium:'Premium Access',practice:'Practice'};

function setView(view, extra={}){
 clearInterval(examClock);examClock=undefined;
 state.view=view;
 if(extra.filter!==undefined)state.topicFilter=extra.filter;
 $('#currentView').textContent=navMap[view]||'NamMath AS';closeMenu();
 $$('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.view===view && (view!=='topics'||b.dataset.filter===state.topicFilter)));
 closeMenu();render();window.scrollTo({top:0,behavior:'smooth'});
}
function closeMenu(){$('#sidebar').classList.remove('open');$('#scrim').classList.add('hidden')}
function openMenu(){$('#sidebar').classList.add('open');$('#scrim').classList.remove('hidden')}
function toast(message){const t=$('#toast');t.textContent=message;t.classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.add('hidden'),3800)}
function modal(title,body,compact=false){$('#modalRoot').innerHTML=`<div class="modal-backdrop" role="dialog" aria-modal="true" aria-label="${escapeHtml(title)}"><div class="modal"><button class="modal-close" aria-label="Close dialog" data-action="close-modal">×</button><div class="eyebrow">NAMMATH AS</div><h2>${escapeHtml(title)}</h2>${body}</div></div>`;if(!compact)$('#modalRoot .modal').focus?.()}
function closeModal(){if(previewPdfUrl){URL.revokeObjectURL(previewPdfUrl);previewPdfUrl=null;}$('#modalRoot').innerHTML=''}
function statBlock(icon,title,value,hint){return `<div class="stat-card"><div class="stat-icon">${icon}</div><div class="stat-caption">${escapeHtml(title)}</div><div class="flex-between"><div class="stat-number">${escapeHtml(value)}</div><div class="stat-small">${escapeHtml(hint)}</div></div></div>`}
const totalAttempts=()=>Object.values(state.attempts).reduce((s,p)=>s+(p.attempts||0),0);
const passed=()=>Object.values(state.attempts).filter(p=>p.correct).length;
const explored=()=>new Set(Object.keys(state.attempts).map(q=>sampleQuestions.find(x=>x.id===q)?.topicId || topics.find(t=>q.startsWith('q-'+t.id))?.id).filter(Boolean)).size;
const average=()=>totalAttempts() ? Math.round((passed()/Math.max(1,Object.keys(state.attempts).length))*100)+'%' : '—';
const isTopicPractised = (t) => Object.keys(state.attempts).some(k => k==='q-'+t.id || k.startsWith('q-'+t.id+'-'));
function topicCard(t){const did=isTopicPractised(t);return `<button class="topic-card" data-action="topic" data-id="${escapeHtml(t.id)}"><div class="topic-top"><div class="topic-symbol">${escapeHtml(t.symbol)}</div><div class="topic-badge">${escapeHtml(t.tag)}</div></div><h3>${escapeHtml(t.short)}</h3><div class="topic-foot"><span>Paper ${t.paper} · Topic ${t.n}${did?' · Practised':''}</span><span class="arrow">↗</span></div></button>`}
const demoNotice=()=>!backendConfigured?'<div class="demo-flag"><strong>Interactive preview:</strong> this version saves practice progress on this device. Live sign-in, secure subscription verification and online payments are not yet activated.</div>':'';
function banner(){return `<div class="premium-banner"><div class="flex-between"><div class="badge-icon">✦</div><div><strong>Study smarter. Unlock every step.</strong><p>Get complete worked memorandums and learn how marks are awarded — from N$30.</p></div></div><button class="button-dark" data-view="premium">Explore Premium <span>↗</span></button></div>`}
function hero(){return `<section class="hero"><div class="hero-text"><div class="hero-kicker">✦ YOUR AS MATHEMATICS JOURNEY STARTS HERE</div><h1>Your equation <br/>to <em>success.</em></h1><p>Master every topic, build exam confidence, and take your next step towards outstanding results.</p><button class="button-primary" data-view="topics" data-filter="all">Start practising →</button></div><svg class="hero-curve" viewBox="0 0 470 270" aria-hidden="true"><path d="M15 250H460M40 270V15" stroke="#e9d8b4" stroke-width="3"/><path d="M20 242 C82 237 88 208 128 214 S211 229 234 173 S325 33 459 47" fill="none" stroke="#e5bd72" stroke-width="9" stroke-linecap="round"/><circle cx="234" cy="173" r="10" fill="#e5bd72"/><circle cx="459" cy="47" r="10" fill="#e5bd72"/></svg></section>`}
function renderHome(){const recent=topics.filter(isTopicPractised);const shown=[...recent.slice(-2).reverse(),...topics.filter(t=>!recent.includes(t))].slice(0,6);return `${hero()}<div class="stat-grid">${statBlock('◈','Topics explored',explored()+' / 15','Keep going')}${statBlock('◎','Questions attempted',totalAttempts(),'Practice')}${statBlock('◉','Correct latest answers',passed(),'Sample items')}${statBlock('✧','Membership',state.premium?'Premium':'Free',state.premium?'Active':'Upgrade ↗')}</div><section class="section"><div class="flex-between"><div><h2 class="section-title">Choose your study path</h2><p class="section-sub">Build a strong foundation, one topic at a time.</p></div></div><div class="paper-grid"><button class="paper-card" data-view="topics" data-filter="1"><div class="paper-illustration">∑</div><div><h3>Mathematics 1</h3><p>Core algebra, graphs, geometry, calculus and more.</p><div class="paper-meta">9 topics to explore →</div></div></button><button class="paper-card" data-view="topics" data-filter="2"><div class="paper-illustration dark">∫</div><div><h3>Mathematics 2</h3><p>Advanced techniques, logarithms and numerical methods.</p><div class="paper-meta">6 topics to explore →</div></div></button></div></section><section class="section"><div class="flex-between"><div><h2 class="section-title">${recent.length?'Keep your momentum':'Start with these topics'}</h2><p class="section-sub">45 original practice questions aligned to NSSCAS topics (demo bank).</p></div><button class="button-ghost btn-small" data-view="topics" data-filter="all">View all topics ↗</button></div><div class="topic-grid">${shown.map(topicCard).join('')}</div></section><section class="section"><div class="flex-between"><div><h2 class="section-title">Your exam resource library</h2><p class="section-sub">Past papers, regional mocks, and concise original study notes.</p></div></div><div class="resource-shortcuts"><button class="shortcut" data-view="past"><span>▧</span><strong>2021–2025 Past Papers</strong><small>Paper 1 and Paper 2</small></button><button class="shortcut" data-view="regional"><span>◎</span><strong>2026 Regional Mocks</strong><small>Upload by region</small></button><button class="shortcut" data-view="notes"><span>✎</span><strong>Topic Study Notes</strong><small>Mathematics 1 and 2</small></button></div></section>${banner()}${demoNotice()}`}
function renderTopics(){const filtered=topics.filter(t=>(state.topicFilter==='all'||String(t.paper)===state.topicFilter)&&(`${t.title} ${t.tag}`.toLowerCase().includes(state.search.toLowerCase())));return `<div class="eyebrow">THE NSSCAS MATHEMATICS SYLLABUS</div><h1 class="page-title">Explore every topic.</h1><p class="subtitle">15 topics across Mathematics 1 and 2. Choose a topic and practise from our growing bank of original questions.</p><div class="searchbar"><input id="topicSearch" value="${escapeHtml(state.search)}" placeholder="⌕  Search by topic or concept…" aria-label="Search topics" /><div class="pill-tabs"><button class="pill ${state.topicFilter==='all'?'active':''}" data-action="filter" data-filter="all">All 15</button><button class="pill ${state.topicFilter==='1'?'active':''}" data-action="filter" data-filter="1">Mathematics 1</button><button class="pill ${state.topicFilter==='2'?'active':''}" data-action="filter" data-filter="2">Mathematics 2</button></div></div>${filtered.length?`<div class="topic-grid">${filtered.map(topicCard).join('')}</div>`:'<div class="empty">No topics match that search. Try a different keyword.</div>'}${banner()}${demoNotice()}`}
function badgeAvailable(has,label){return `<span class="resource-status ${has?'ok':'pending'}">${has?'✓':'○'} ${escapeHtml(label)}</span>`;}
function resourceCard(entry){
 const category=entry.category==='past'?'Past paper':`${entry.region} mock`;
 const available=Boolean(entry.paper_path);
 const memo=Boolean(entry.memo_path);
 const key=resourceKey(entry.category,entry.year,entry.region,entry.paper);
 return `<article class="resource-card" data-key="${escapeHtml(key)}"><div class="resource-card-top"><span class="eyebrow">${escapeHtml(category)} · ${entry.year}</span><span class="paper-chip">P${entry.paper}</span></div><h3>${entry.category==='past'?entry.year+' Examination':escapeHtml(entry.region)+' · 2026'} — Paper ${entry.paper}</h3><div class="resource-badges">${badgeAvailable(available,available?'Clean paper ready':'Clean paper pending')}${badgeAvailable(memo,memo?'Memo ready':'Memo pending')}</div><div class="resource-actions"><button class="button-primary btn-small" data-action="open-resource" data-kind="paper" data-key="${escapeHtml(key)}" ${!available?'disabled':''}>${available?'View clean paper ↗':'Awaiting PDF'}</button>${memo?`<button class="button-outline btn-small" data-action="open-resource" data-kind="memo" data-key="${escapeHtml(key)}">${state.premium?'View premium memo ◇':'🔒 Unlock memo'}</button>`:`<button class="button-outline btn-small" disabled>Memo coming soon</button>`}</div><div class="file-label">${available?escapeHtml(entry.paper_filename||'Paper PDF'):'No PDF uploaded'}${memo?' · Memo attached':''}</div></article>`;
}
function renderLibrary(category){const isPast=category==='past';const rows=mergeCatalogue(state.library).filter(r=>r.category===category);const regions=[...new Set(rows.map(r=>r.region).filter(Boolean))].sort();return `<div class="eyebrow">EXAM RESOURCE LIBRARY</div><h1 class="page-title">${isPast?'Past examination papers.':'2026 regional mock examinations.'}</h1><p class="subtitle">${isPast?'Clean Mathematics 1 and Mathematics 2 papers from 2021 to 2025, each with its own premium memo slot.': 'Browse regional Mathematics 1 and Mathematics 2 mocks. Regions appear here once their documents are uploaded.'} <strong>Empty slots do not represent uploaded papers.</strong></p><div class="library-tabs"><button class="pill ${isPast?'active':''}" data-view="past">2021–2025 Past Papers</button><button class="pill ${!isPast?'active':''}" data-view="regional">2026 Regional Mocks</button></div>${!isPast&&regions.length?`<div class="region-cloud">${regions.map(r=>`<span class="chip">${escapeHtml(r)}</span>`).join('')}</div>`:''}${rows.length?`<div class="resource-grid">${rows.map(resourceCard).join('')}</div>`:`<div class="empty-state"><div style="font-size:38px">▧</div><h3>No regional mock exams uploaded yet</h3><p>Go to Content Studio to add a region and upload a clean Paper 1 or Paper 2 PDF. The memo can be attached separately.</p>${state.isAdmin?'<button class="button-primary" data-view="studio">Add first regional mock →</button>':''}</div>`}<div class="library-policy"><strong>Free questions · Paid explanations.</strong> Clean papers are intended to be freely viewable. Full uploaded worked memorandums require an active NamMath AS Premium account. PDF screenshots and external-camera recording cannot be reliably blocked in a web app.</div>${demoNotice()}`;}
function noteText(value){return `<span class="math-content">${escapeHtml(value||'Not added yet.').replace(/\n/g,'<br>')}</span>`;}
function notePanel(topic){const note=state.notes[topic.id]||{};return `<article class="note-card" id="note-${escapeHtml(topic.id)}"><div class="note-heading"><span class="topic-badge">MATHEMATICS ${topic.paper} · ${topic.n}</span><span class="note-symbol">${escapeHtml(topic.symbol)}</span></div><h3>${escapeHtml(topic.title)}</h3><div class="note-section"><div class="note-label">CONCEPT SUMMARY</div><p>${noteText(note.summary)}</p></div><div class="note-section note-formula"><div class="note-label">KEY FORMULAS</div><p>${noteText(note.formulas)}</p></div><div class="note-section"><div class="note-label">WORKED MINI EXAMPLE</div><p>${noteText(note.example)}</p></div><div class="note-tip"><strong>Exam tip</strong><p>${noteText(note.tip)}</p></div><div class="note-pitfall"><strong>Common mistake</strong><p>${noteText(note.pitfall)}</p></div><div class="note-footer"><span>Original NamMath AS revision summary · Review before exam use</span><button class="button-outline btn-small" data-action="topic" data-id="${escapeHtml(topic.id)}">Practise topic →</button></div></article>`;}
function renderNotes(){const filtered=topics.filter(t=>String(t.paper)===state.notesPaper);return `<div class="eyebrow">AI-PREPARED • TEACHER-EDITABLE</div><h1 class="page-title">Summarised mathematics notes.</h1><p class="subtitle">Original condensed revision notes, key formulas, mini examples, and exam tips for each NSSCAS Mathematics topic. These are drafts to be reviewed by a subject teacher before publication.</p><div class="library-tabs"><button class="pill ${state.notesPaper==='1'?'active':''}" data-action="notes-paper" data-paper="1">Mathematics 1 · 9 topics</button><button class="pill ${state.notesPaper==='2'?'active':''}" data-action="notes-paper" data-paper="2">Mathematics 2 · 6 topics</button></div><div class="note-index">${filtered.map(t=>`<button class="note-index-item" data-action="jump-note" data-id="${escapeHtml(t.id)}">${t.n}. ${escapeHtml(t.short)}</button>`).join('')}</div><div class="notes-layout">${filtered.map(notePanel).join('')}</div>${state.isAdmin?'<button class="button-outline" data-view="studio">✎ Edit summaries in Content Studio</button>':''}${demoNotice()}`;}
function renderStudio(){if(!state.isAdmin)return `<div class="empty-state"><h2>Admin access only</h2><p>Sign in with an approved NamMath AS administrator account to manage documents and summaries.</p><button class="button-primary" data-action="show-auth">Sign in →</button></div>`;const editable=topics.find(t=>t.id===state.selectedNote)||topics[0];const note=state.notes[editable.id]||{};return `<div class="eyebrow">CONTENT MANAGEMENT WORKSPACE</div><h1 class="page-title">Content Studio.</h1><p class="subtitle">Upload clean PDF examination papers and separately attach worked memos, or edit free revision notes. ${backendConfigured?'Only approved administrators can access these controls.':'Preview uploads stay inside this browser and are not published to learners.'}</p>${!backendConfigured?'<div class="demo-flag"><strong>LOCAL DEMO:</strong> Files are stored in this browser using IndexedDB. Do not treat this as a shared, secure upload service. Premium memos remain locked in the learner preview.</div>':''}<div class="studio-grid"><section class="white-card"><div class="eyebrow">01 · PDF LIBRARY</div><h2 class="section-title">Upload a paper or memo</h2><form id="resourceForm" class="stack-form"><label>Library<select name="category" id="resourceCategory"><option value="past">2021–2025 Past Papers</option><option value="mock">2026 Regional Mock Exams</option></select></label><label id="resourceYearGroup">Examination year<select name="year">${[2025,2024,2023,2022,2021].map(y=>`<option value="${y}">${y}</option>`).join('')}</select></label><label id="regionField" class="hidden">Region / mock identifier<input name="region" placeholder="e.g. Khomas, Erongo, Otjozondjupa" maxlength="75"></label><label>Paper<select name="paper"><option value="1">Paper 1 — Mathematics 1</option><option value="2">Paper 2 — Mathematics 2</option></select></label><label>Document<select name="kind"><option value="paper">Clean examination paper (free)</option><option value="memo">Worked memorandum (Premium)</option></select></label><label>PDF upload · Max 20 MB<input type="file" name="file" accept="application/pdf,.pdf" required></label><button class="button-primary" type="submit" id="uploadButton">Upload PDF →</button><p class="fineprint">Only upload material you have permission to distribute. Memos are private in the connected version.</p></form></section><section class="white-card"><div class="eyebrow">02 · STUDY NOTES</div><h2 class="section-title">Edit topic summaries</h2><form id="notesForm" class="stack-form"><label>Topic<select name="topicId" id="noteTopicSelect">${topics.map(t=>`<option value="${escapeHtml(t.id)}" ${editable.id===t.id?'selected':''}>Mathematics ${t.paper} · ${t.short}</option>`).join('')}</select></label><div class="math-help"><strong>Maths notation: LaTeX + KaTeX</strong><span>Use <code>\(x^2+1\)</code> for inline math or <code>$$\\frac{a}{b}$$</code> for a centred equation. Only write LaTeX inside delimiters. A live preview appears below.</span><div class="math-toolbar"><button type="button" class="button-outline" data-action="insert-math" data-math="fraction">+ Fraction</button><button type="button" class="button-outline" data-action="insert-math" data-math="integral">+ Integral</button><button type="button" class="button-outline" data-action="insert-math" data-math="power">+ Power</button><button type="button" class="button-outline" data-action="insert-math" data-math="matrix">+ Matrix</button></div></div><label>Concept summary<textarea name="summary" rows="4" required>${escapeHtml(note.summary)}</textarea></label><label>Key formulas · use <code>$$...$$</code> for each display equation<textarea name="formulas" rows="5" required>${escapeHtml(note.formulas)}</textarea></label><label>Worked mini example<textarea name="example" rows="3" required>${escapeHtml(note.example)}</textarea></label><label>Exam tip<textarea name="tip" rows="3" required>${escapeHtml(note.tip)}</textarea></label><label>Common mistake<textarea name="pitfall" rows="3" required>${escapeHtml(note.pitfall)}</textarea></label><div class="editor-preview-heading"><strong>Live mathematical preview</strong><span>Updated as you type</span></div><div id="mathErrors" class="math-errors hidden" role="alert"></div><div id="noteEditorPreview" class="editor-preview"></div><button class="button-primary" type="submit" id="saveNotesButton">Save topic notes →</button><button class="button-outline" type="button" data-action="restore-draft" data-id="${escapeHtml(editable.id)}">Restore prepared ChatGPT draft</button><p class="fineprint">Initial notes were drafted by ChatGPT and need teacher review. This editor does not call AI automatically.</p></form></section></div>`;}
async function loadContent(){if(!state.supabase)return;const [resourceResp,noteResp]=await Promise.all([state.supabase.from('nammath_library').select('*').eq('published',true).order('year',{ascending:false}),state.supabase.from('nammath_notes').select('topic_id,summary,formulas,example,tip,pitfall').eq('published',true)]);if(!resourceResp.error)state.library=resourceResp.data||[];if(!noteResp.error)state.notes={...preparedNotes,...Object.fromEntries((noteResp.data||[]).map(n=>[n.topic_id,n]))};render();}
async function detectAdmin(){if(!state.supabase||!state.user){state.isAdmin=false;$('#studioNav').classList.add('hidden');return;}const {data,error}=await state.supabase.functions.invoke('nam-math-library-admin',{body:{action:'status'}});state.isAdmin=!error&&Boolean(data?.admin);$('#studioNav').classList.toggle('hidden',!state.isAdmin);}
function getEntry(key){return mergeCatalogue(state.library).find(x=>resourceKey(x.category,x.year,x.region,x.paper)===key);}
async function openResource(key,kind){const entry=getEntry(key);if(!entry||!entry[`${kind}_path`]){toast('This document has not been uploaded.');return;}if(kind==='memo'&&!state.premium){setView('premium');toast('An active N$30 membership is needed for full memorandums.');return;}if(backendConfigured){if(!state.supabase){toast('Connection unavailable.');return;}const {data,error}=await state.supabase.functions.invoke('nam-math-document',{body:{resourceId:entry.id,kind}});if(error||!data?.url){toast('Unable to open document. Check your membership or try again.');return;}return showPdf(data.url,entry,kind,data.watermark||state.user?.email||'');}
 if(kind==='memo'){toast('Premium memos cannot be opened in the offline preview.');return;}
 try{const blob=await loadPreviewPdf(`${key}:${kind}`);if(!blob){toast('Preview PDF not found on this device.');return;}previewPdfUrl=URL.createObjectURL(blob);showPdf(previewPdfUrl,entry,kind,'');}catch(e){toast('Unable to load this browser-local PDF.');}
}
function showPdf(url,entry,kind,watermark){const heading=`${entry.category==='past'?entry.year+' Past Paper':entry.region+' Mock'} · P${entry.paper} · ${kind==='memo'?'Premium Memorandum':'Clean Paper'}`;modal(heading,`<div class="pdf-info">${kind==='memo'?'🔒 Licensed premium view · Short-lived access link':'Free study resource · PDF preview'}</div><div class="pdf-container"><iframe title="${escapeHtml(heading)}" src="${escapeHtml(url)}#toolbar=0" loading="lazy"></iframe>${watermark?`<div class="pdf-watermark" aria-hidden="true">${Array(5).fill(`<span>${escapeHtml(watermark)} · ${escapeHtml(new Date().toLocaleDateString('en-NA'))}</span>`).join('')}</div>`:''}</div><p class="fineprint">${kind==='memo'?'Watermarks discourage copying but cannot prevent screenshots, downloads or photographs.':'Check that the paper matches the exam year and subject before using it.'}</p>`,true);}
async function handleResourceUpload(form){const fd=new FormData(form);const file=fd.get('file');const error=await validatePdf(file);if(error){toast(error);return;}const category=fd.get('category');const year=category==='mock'?2026:Number(fd.get('year'));const paper=Number(fd.get('paper'));const region=category==='mock'?String(fd.get('region')||'').trim():'';const kind=fd.get('kind');if(category==='mock'&&!/^[\p{L}\p{N} .,&'()-]{2,75}$/u.test(region)){toast('Enter a valid region or mock examination identifier.');return;}const key=resourceKey(category,year,region,paper);const button=$('#uploadButton');button.disabled=true;button.textContent='Uploading…';try{let update;if(!backendConfigured){const storage=await storePreviewPdf(`${key}:${kind}`,file);if(storage==='session')toast('This browser cannot persist PDF uploads. Your file is available only until the tab closes.');update={category,year,region,paper,resource_key:key,[`${kind}_filename`]:file.name,[`${kind}_path`]:`${key}:${kind}`,published:true};const old=state.library.find(r=>resourceKey(r.category,r.year,r.region,r.paper)===key)||{};const combined={...old,...update};state.library=[...state.library.filter(r=>resourceKey(r.category,r.year,r.region,r.paper)!==key),combined];writeLocal(LIBRARY_KEY,state.library);}
 else {if(!state.supabase||!state.isAdmin)throw Error('Admin authentication required');const reserve=await state.supabase.functions.invoke('nam-math-library-admin',{body:{action:'reserve',category,year,region,paper,kind,filename:file.name,size:file.size}});if(reserve.error||!reserve.data?.token)throw Error('Unable to authorise upload.');const {path,token}=reserve.data;const {error:uploadError}=await state.supabase.storage.from('nammath-library').uploadToSignedUrl(path,token,file,{contentType:'application/pdf'});if(uploadError)throw uploadError;const finish=await state.supabase.functions.invoke('nam-math-library-admin',{body:{action:'finalize',category,year,region,paper,kind,filename:file.name,path}});if(finish.error||!finish.data?.ok)throw Error('Upload transferred but could not be registered.');await loadContent();}
 toast(`${kind==='paper'?'Clean paper':'Memorandum'} saved successfully${backendConfigured?'':' in this browser only'}.`);form.reset();$('#regionField').classList.add('hidden');$('#resourceYearGroup').classList.remove('hidden');}catch(err){console.warn(err);toast('Upload failed: '+(err.message||'Please try again.'));}finally{button.disabled=false;button.textContent='Upload PDF →';}}
const mathSnippets={
 fraction:String.raw`$$\frac{a}{b}$$`,
 integral:String.raw`$$\int_a^b f(x)\,\mathrm dx$$`,
 power:String.raw`\(x^{n+1}\)`,
 matrix:String.raw`$$\begin{pmatrix}a&b\\c&d\end{pmatrix}$$`
};
function insertMathSnippet(kind){
 const form=$('#notesForm');if(!form)return;
 const field=form.querySelector('textarea:focus')||form.querySelector('textarea[name=formulas]');
 const snip=mathSnippets[kind];if(!snip||!field)return;
 const start=field.selectionStart??field.value.length;const end=field.selectionEnd??start;
 // Put display equations on their own lines when inserted into existing notes.
 const before=field.value.slice(0,start),after=field.value.slice(end);
 const insertion=(before&&!before.endsWith('\n')?'\n':'')+snip+(after&&!after.startsWith('\n')?'\n':'');
 field.setRangeText(insertion,start,end,'end');field.focus();refreshEditorPreview();
}
function refreshEditorPreview(){
 const form=$('#notesForm');const target=$('#noteEditorPreview');if(!form||!target)return;
 const topic=topics.find(t=>t.id===form.elements.topicId.value)||topics[0];
 const content=Object.fromEntries(['summary','formulas','example','tip','pitfall'].map(k=>[k,form.elements[k].value]));
 const allErrors=Object.entries(content).flatMap(([field,text])=>validateMathText(text).map(err=>`${field}: ${err}`));
 const errorBox=$('#mathErrors');if(errorBox){errorBox.classList.toggle('hidden',!allErrors.length);errorBox.textContent=allErrors.length?`⚠ ${allErrors.length} LaTeX error(s): ${allErrors.slice(0,3).join(' | ')}`:'';}
 target.innerHTML=`<div class="preview-mini-label">${escapeHtml(topic.title)} · Mathematics ${topic.paper}</div><div class="preview-section"><strong>Concept</strong><div>${noteText(content.summary)}</div></div><div class="preview-section preview-formulas"><strong>Key formulas</strong><div>${noteText(content.formulas)}</div></div><div class="preview-section"><strong>Worked example</strong><div>${noteText(content.example)}</div></div><div class="preview-section"><strong>Exam tip</strong><div>${noteText(content.tip)}</div></div><div class="preview-section"><strong>Common mistake</strong><div>${noteText(content.pitfall)}</div></div>`;
 typesetNotes(target);
}
async function handleNoteSave(form){const fd=new FormData(form),id=String(fd.get('topicId')||'');if(!topics.some(t=>t.id===id))return;const n={summary:String(fd.get('summary')||'').trim(),formulas:String(fd.get('formulas')||'').trim(),example:String(fd.get('example')||'').trim(),tip:String(fd.get('tip')||'').trim(),pitfall:String(fd.get('pitfall')||'').trim()};if(Object.values(n).some(x=>!x||x.length>6000)){toast('Please complete all fields (up to 6000 characters per field).');return;}const invalid=Object.entries(n).flatMap(([field,v])=>validateMathText(v).map(e=>field+': '+e));if(invalid.length){toast('Please correct LaTeX errors shown in the live preview before saving.');refreshEditorPreview();return;}if(backendConfigured){if(!state.supabase||!state.isAdmin){toast('Administrator sign-in required.');return;}const {error}=await state.supabase.from('nammath_notes').upsert({topic_id:id,...n,published:true},{onConflict:'topic_id'});if(error){toast('Unable to save notes: '+error.message);return;}}state.notes[id]=n;if(!backendConfigured)writeLocal(NOTES_KEY,Object.fromEntries(Object.entries(state.notes).filter(([k,v])=>JSON.stringify(v)!==JSON.stringify(preparedNotes[k]))));toast('Topic summary saved.');}

function renderPapers(){return `<div class="eyebrow">PREPARE WITH PURPOSE</div><h1 class="page-title">Exam practice centre.</h1><p class="subtitle">Start a timed mini mock with one question from each topic in the selected paper. These are <strong>not official past examination papers</strong>.</p><div class="mock-grid">${[1,2].map(p=>`<div class="mock-card"><div class="paper-illustration ${p===2?'dark':''}">${p===1?'∑':'∫'}</div><span class="eyebrow">PAPER ${p} · MINI MOCK</span><h3>Mathematics ${p}</h3><p>A timed checkpoint covering ${p===1?'all nine Mathematics 1':'all six Mathematics 2'} topic areas.</p><div class="mock-meta"><span class="chip">◷ ${p===1?'25':'20'} minutes</span><span class="chip">▤ ${p===1?'9':'6'} questions</span><span class="chip">✦ Original practice</span></div><button class="button-primary" data-action="start-exam" data-paper="${p}">Start mini mock →</button></div>`).join('')}</div>${demoNotice()}`}
function renderProgress(){return `<div class="eyebrow">YOUR LEARNING JOURNEY</div><h1 class="page-title">Every question counts.</h1><p class="subtitle">Watch your confidence grow, topic by topic.</p><div class="stat-grid">${statBlock('◈','Topics explored',explored()+' / 15','Syllabus')}${statBlock('◎','Total attempts',totalAttempts(),'Questions')}${statBlock('◉','Correct latest answers',passed(),'Practice')}${statBlock('◇','Topic coverage',Math.round(explored()/15*100)+'%','Topics')}</div><section class="section"><div class="flex-between"><div><h2 class="section-title">Topic activity</h2><p class="section-sub">Each topic contains multiple practice questions.</p></div></div><div class="progress-list">${topics.map(t=>{const results=Object.entries(state.attempts).filter(([id])=>id==='q-'+t.id || id.startsWith('q-'+t.id+'-'));const correctCount=results.filter(([_,r])=>r.correct).length;const totalCount=backendConfigured?Math.max(3,results.length):3;return `<div class="progress-item"><div><strong>${escapeHtml(t.short)}</strong><p>Mathematics ${t.paper} · ${results.length} answered</p></div><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,100*correctCount/totalCount)}%"></div></div><div class="right">${!results.length?'Not started':`${correctCount}/${results.length} correct`}</div></div>`}).join('')}</div></section>${demoNotice()}`}
function renderPremium(){return `<div class="eyebrow">NAMMATH AS PREMIUM</div><h1 class="page-title">Understand the steps. Earn the marks.</h1><p class="subtitle">Practise for free, then unlock full worked memorandums when you need more support.</p><div class="price-layout"><div class="pricing-card"><div class="hero-kicker">✦ PREMIUM MEMORANDUM ACCESS</div><div class="price">N$30 <small>/ 30 days</small></div><p style="color:#d7cdbb;font-size:13px">Full solutions, marking guidance and more confidence before exam day.</p><ul class="features"><li>Complete worked mathematics memorandums</li><li>Clear, step-by-step explanations</li><li>Account-based premium access</li><li>Personalised on-screen watermarking</li><li>Access expires automatically after 30 days</li></ul><button class="button-primary" data-action="subscribe">${state.premium?'Premium is active ✓':'Unlock Premium →'}</button><p class="fineprint">${state.premium?`Access valid until ${escapeHtml(new Date(state.expiry).toLocaleDateString('en-NA'))}.`:'Payments are not active in this first development preview. No money will be charged.'}</p></div><div class="white-card"><h2 class="section-title">Why NamMath Premium?</h2><p class="section-sub" style="margin-bottom:26px">Learn the mathematical reasoning behind every answer.</p><div class="feature-list"><div class="feature-point"><div class="circle">▤</div><div><strong>Questions stay free</strong><p>Practise sample questions and explore the syllabus without paying.</p></div></div><div class="feature-point"><div class="circle">✎</div><div><strong>Detailed memorandums</strong><p>Get worked solutions delivered only after server-side subscription verification.</p></div></div><div class="feature-point"><div class="circle">◇</div><div><strong>Account-linked protection</strong><p>Each premium explanation can display an identifiable watermark to discourage sharing.</p></div></div><div class="feature-point"><div class="circle">♢</div><div><strong>Built for Namibian learners</strong><p>Focused on the NSSCAS Mathematics 1 and Mathematics 2 syllabus.</p></div></div></div><div class="demo-flag" style="margin-top:27px">Web browsers cannot reliably block screenshots. Android-native screenshot protection may be added in a later companion app.</div></div></div>`}
function getQuestion(){return state.questions[state.index]}
function renderPractice(){const q=getQuestion();if(!q)return `<h1>Practice not available.</h1><button data-view="topics" class="button-primary">Back to topics</button>`;const t=topics.find(x=>x.id===q.topicId);const total=state.questions.length;const time=state.timerEnd?Math.max(0,Math.ceil((state.timerEnd-Date.now())/1000)):null;const title=state.mode==='mock'?`Mathematics ${state.mockPaper} — mini mock`:t?.short||'Topic practice';return `<div class="flex-between"><div><div class="eyebrow">${state.mode==='mock'?'TIMED MINI MOCK':'TOPIC PRACTICE'} • MATHEMATICS ${t?.paper||1}</div><h1 class="page-title">${escapeHtml(title)}</h1><p class="subtitle">${state.mode==='mock'?'Answer each question before moving to the next.':'Work through this original sample question at your own pace.'}</p></div><button class="button-outline btn-small" data-action="exit-practice">← Exit</button></div><div class="practice-layout"><div class="question-panel"><div class="flex-between"><div class="question-count">QUESTION ${state.index+1} OF ${total}</div><span class="chip">${state.mode==='mock'?'1 mark · Timed':'1 mark · Practice'}</span></div><div class="question-prompt">${escapeHtml(q.prompt)}</div><div class="options">${q.options.map((option,i)=>`<button class="option ${state.selected===i?'selected':''} ${state.graded&&state.selected===i?(state.gradeResult?.correct?'correct':'incorrect'):''}" data-action="choose" data-index="${i}" ${state.graded?'disabled':''}><span class="option-key">${'ABCD'[i]}</span><span>${escapeHtml(option)}</span></button>`).join('')}</div>${state.graded?`<div class="feedback ${state.gradeResult?.correct?'':'bad'}" role="status">${state.gradeResult?.correct?'✓ Well done! Your answer is correct.':'Not quite. Take a moment to review this topic and try again later.'}</div>`:''}<div class="question-actions">${!state.graded?`<button class="button-primary" data-action="check" ${state.selected<0?'disabled':''}>${state.mode==='mock'?'Submit answer':'Check answer'} →</button>`:`<button class="button-primary" data-action="next-question">${state.index===total-1?'Finish practice':'Next question'} →</button>`}<button class="button-outline" data-action="view-memo">${state.premium?'View full memo ◇':'Unlock full memo ◇'}</button></div></div><div class="side-panel"><h3>${state.mode==='mock'?'Exam checkpoint':'Your practice session'}</h3><div class="panel-row"><span>Question progress</span><b>${state.index+1}/${total}</b></div><div class="progress-track"><div class="progress-fill" style="width:${Math.round((state.index+1)/total*100)}%"></div></div>${state.mode==='mock'?`<div style="margin:20px 0 12px;font-size:12px;color:#a18252">◷ Time remaining</div><div id="examTime" style="font-size:31px;font-weight:850">${formatTime(time)}</div>`:''}<div style="height:24px"></div><div class="lock-box"><div class="lock-glyph">◇</div><h3>Premium Memorandum</h3><p>Step-by-step workings, answers and marking guidance are reserved for Premium learners.</p><button class="button-outline btn-small" data-action="view-memo">${state.premium?'View memorandum':'Unlock for N$30'}</button></div></div></div>${demoNotice()}`}
function formatTime(s){if(s===null)return '';return `${Math.floor(Math.max(0,s)/60).toString().padStart(2,'0')}:${(Math.max(0,s)%60).toString().padStart(2,'0')}`}
function renderResults(){
 const answers=state.quizResults||[];const correct=answers.filter(x=>x.correct).length;const count=answers.length;
 const weak=[...new Set(answers.filter(x=>!x.correct).map(x=>x.topicId))].map(id=>topics.find(t=>t.id===id)).filter(Boolean);
 return `<div class="eyebrow">PRACTICE SESSION COMPLETE</div><h1 class="page-title">You showed up. That's progress.</h1><p class="subtitle">Your session is complete. Use your feedback to focus on areas that need revision.</p><div class="white-card" style="margin-top:25px;max-width:780px"><div class="eyebrow">YOUR RESULT</div><div style="font-size:65px;font-weight:850;letter-spacing:-3px;margin:16px 0">${correct}<span style="font-size:24px;color:#9a8e7d"> / ${count}</span></div><div class="progress-track" style="height:13px"><div class="progress-fill" style="width:${count?100*correct/count:0}%"></div></div><p class="subtitle" style="margin-top:18px">Score: ${count?Math.round(100*correct/count):0}%. These are original practice items, not predictions of official exam performance.</p>${weak.length?`<div class="review-block"><h3>Topics to revisit</h3><p>These topics contained answers you missed in this session.</p><div class="review-list">${weak.map(t=>`<button class="button-outline btn-small" data-action="topic" data-id="${escapeHtml(t.id)}">${escapeHtml(t.short)} →</button>`).join('')}</div></div>`:'<div class="feedback">Excellent work on the completed questions. Keep revising to maintain your confidence.</div>'}<div class="question-actions"><button class="button-primary" data-view="topics" data-filter="all">Revise topics →</button><button class="button-outline" data-view="papers">More mini mocks</button></div></div>`
}
function render(){if(state.view==='home')main.innerHTML=renderHome();if(state.view==='topics')main.innerHTML=renderTopics();if(state.view==='papers')main.innerHTML=renderPapers();if(state.view==='past')main.innerHTML=renderLibrary('past');if(state.view==='regional')main.innerHTML=renderLibrary('mock');if(state.view==='notes')main.innerHTML=renderNotes();if(state.view==='studio')main.innerHTML=renderStudio();if(state.view==='progress')main.innerHTML=renderProgress();if(state.view==='premium')main.innerHTML=renderPremium();if(state.view==='practice')main.innerHTML=renderPractice();if(state.view==='results')main.innerHTML=renderResults();if(state.view==='notes')typesetNotes(main);if(state.view==='studio')refreshEditorPreview();if(state.view==='practice'&&state.timerEnd)startClock();}
function startClock(){clearInterval(examClock);examClock=setInterval(()=>{const remain=Math.max(0,Math.ceil((state.timerEnd-Date.now())/1000));const node=$('#examTime');if(node)node.textContent=formatTime(remain);if(remain<=0){clearInterval(examClock);toast('Time is up. Your completed answers have been saved.');finishSession();}},1000)}
async function startTopic(topicId){state.topic=topics.find(x=>x.id===topicId);if(!state.topic)return;state.mode='topic';state.mockPaper=null;state.index=0;state.quizResults=[];state.timerEnd=null;state.questions=await questionsForTopic(state.topic);if(!state.questions.length){toast('No published questions are available for this topic yet.');return;}state.selected=-1;state.graded=false;state.gradeResult=null;setView('practice')}
async function publicQuestionsForTopics(topicIds){
 if(!state.supabase){toast('Online question bank unavailable. Please reconnect and sign in.');return []}
 const {data,error}=await state.supabase.from('nammath_questions')
  .select('id,topic_id,prompt,options,points').in('topic_id',topicIds)
  .eq('published',true).order('id').limit(180);
 if(error){console.warn('Unable to load public questions:',error.message);toast('The question bank is not available yet. Your account and memorandums remain protected.');return []}
 return (data||[]).map(q=>({...q,topicId:q.topic_id}));
}
async function questionsForTopic(topic){
 if(backendConfigured)return publicQuestionsForTopics([topic.id]); // NEVER fall back to bundled answer keys in online mode.
 return sampleQuestions.filter(q=>q.topicId===topic.id);
}
async function startExam(paper){
 const paperTopics=topics.filter(t=>t.paper===paper);
 let pool=backendConfigured?await publicQuestionsForTopics(paperTopics.map(t=>t.id)):sampleQuestions.filter(q=>paperTopics.some(t=>t.id===q.topicId));
 if(!pool.length){toast('No online questions are available for this paper yet.');return;}
 const chosen=paperTopics.map(t=>pool.filter(q=>q.topicId===t.id).sort((a,b)=>a.id.localeCompare(b.id))[0]).filter(Boolean);
 if(!chosen.length){toast('This paper has no published questions yet.');return;}
 state.mode='mock';state.mockPaper=paper;state.index=0;state.quizResults=[];
 state.questions=chosen;state.selected=-1;state.graded=false;state.gradeResult=null;
 setView('practice');state.timerEnd=Date.now()+(paper===1?25:20)*60*1000;startClock();
}
function chooseAnswer(i){if(state.graded)return;state.selected=i;$$('.option').forEach((el,j)=>el.classList.toggle('selected',i===j));const check=$('[data-action="check"]');if(check)check.disabled=false}
async function checkAnswer(){const q=getQuestion();if(!q||state.selected<0||state.graded)return;let correct=false;
 if(!('answer' in q)&&backendConfigured&&state.user&&state.supabase){const {data,error}=await state.supabase.functions.invoke('nam-math-grade',{body:{questionId:q.id,selectedOption:state.selected}});if(error){toast('Could not verify answer securely. Try again.');return;}correct=Boolean(data?.correct);}
 else if('answer' in q)correct=state.selected===q.answer;else{toast('Please sign in to grade this question.');return;}
 state.graded=true;state.gradeResult={correct};state.quizResults.push({id:q.id,topicId:q.topicId,correct});await saveProgress(q,correct);render();}
async function saveProgress(q,correct){
 const old=state.attempts[q.id]||{attempts:0,correct:false};
 const updated={attempts:old.attempts+1,correct,updated:new Date().toISOString()};
 state.attempts[q.id]=updated;
 if(!backendConfigured){try{localStorage.setItem(DEMO_KEY,JSON.stringify(state.attempts))}catch{}return;}
 if(state.user && state.supabase){
  const {error}=await state.supabase.from('nammath_progress').upsert({user_id:state.user.id,question_id:q.id,attempts:updated.attempts,last_correct:correct,updated_at:updated.updated},{onConflict:'user_id,question_id'});
  if(error)toast('Answer checked, but your online progress could not be saved.');
 }
}
function nextQuestion(){if(state.index>=state.questions.length-1){finishSession();return;}state.index++;state.selected=-1;state.graded=false;state.gradeResult=null;render()}
function finishSession(){clearInterval(examClock);state.timerEnd=null;state.view='results';$('#currentView').textContent='Session Complete';render();window.scrollTo({top:0,behavior:'smooth'})}
async function viewMemo(){if(!state.premium){setView('premium');toast('An active premium subscription is required to view complete memorandums.');return;}if(!state.user||!state.supabase){toast('Sign in to securely view memorandums.');return;}const q=getQuestion();if(!q)return;const {data,error}=await state.supabase.functions.invoke('nam-math-memo',{body:{questionId:q.id}});if(error||!data?.memo){toast('Unable to retrieve your memorandum. Check your subscription.');return;}const account=data.watermark||state.user.email||state.user.id;
 const stamped=new Date().toLocaleString('en-NA',{dateStyle:'medium',timeStyle:'short'});
 const mark=escapeHtml(`${account} · ${stamped}`);
 modal('Protected Memorandum',`<div class="notice">◇ Premium access verified · Account watermarked</div><div class="memo-box"><div class="memo-watermark" aria-hidden="true">${Array(9).fill(`<span>${mark}</span>`).join('')}</div><pre id="memoContent"></pre></div><p class="memo-owner">Licensed to ${escapeHtml(account)} · ${escapeHtml(stamped)}</p><p>For individual study use only. Watermarks discourage unauthorised sharing, but web browsers cannot block screenshots.</p>`);$('#memoContent').textContent=data.memo;}
function showAuth(){if(!backendConfigured){modal('Learner account',`<p>Online learner sign-in is not connected in this development preview. Practice the demo now, or set the Supabase publishable configuration to activate authentication.</p><button class="button-primary" data-action="close-modal">Continue demo</button>`);return;}if(state.user){modal('Your account',`<p><strong>${escapeHtml(state.user.email)}</strong></p><p>Membership: ${state.premium?'Premium (active)':'Free learner'}</p><button class="button-primary" data-action="signout">Sign out</button>`);return;}renderAuthModal()}
function renderAuthModal(){modal(state.authMode==='signin'?'Welcome back':'Create your learner account',`<p>Sign ${state.authMode==='signin'?'in':'up'} securely to sync your learning and access premium when payments are connected.</p><form id="authForm"><label>Email address<input required type="email" name="email" autocomplete="email" placeholder="learner@example.com"></label><label>Password<input required type="password" minlength="10" name="password" autocomplete="${state.authMode==='signin'?'current-password':'new-password'}" placeholder="At least 10 characters"></label><button class="button-primary" type="submit">${state.authMode==='signin'?'Sign in':'Create account'}</button></form><button class="button-ghost" style="width:100%;margin-top:14px" data-action="toggle-auth">${state.authMode==='signin'?'New here? Create account':'Already registered? Sign in'}</button>${state.authMode==='signin'?'<button class="button-ghost" style="width:100%;margin-top:6px" data-action="password-reset">Forgot your password?</button>':''}`)}
async function requestPasswordReset(){
 if(!state.supabase)return;
 const email=$('#authForm [name=email]')?.value?.trim();
 if(!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){toast('Enter your email address first, then select password reset.');return;}
 const {error}=await state.supabase.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});
 if(error){toast(error.message);return;}
 closeModal();toast('If the address is registered, you will receive a password-reset email.');
}
async function promptNewPassword(){
 if(!state.supabase)return;
 modal('Set a new password',`<p>Enter a new password for your NamMath AS account.</p><form id="newPasswordForm"><label>New password<input type="password" autocomplete="new-password" name="password" minlength="10" required placeholder="At least 10 characters" /></label><button type="submit" class="button-primary">Save new password</button></form>`);
}
async function submitNewPassword(form){
 if(!state.supabase)return;
 const {error}=await state.supabase.auth.updateUser({password:form.elements.password.value});
 if(error){toast(error.message);return}
 closeModal();toast('Password updated successfully.');
}
async function submitAuth(form){if(!state.supabase)return;const email=form.email.value.trim(),password=form.password.value;const button=form.querySelector('[type=submit]');button.disabled=true;button.textContent='Please wait…';const response=state.authMode==='signin'?await state.supabase.auth.signInWithPassword({email,password}):await state.supabase.auth.signUp({email,password});if(response.error){toast(response.error.message);button.disabled=false;button.textContent=state.authMode==='signin'?'Sign in':'Create account';return;}closeModal();if(state.authMode==='signup'&&!response.data.session)toast('Check your email to confirm your account before signing in.');else toast('Signed in successfully.');await syncUser();render()}
async function syncUser(){if(!state.supabase)return;const {data:{user}}=await state.supabase.auth.getUser();state.user=user||null;await detectAdmin();$('#authLabel').textContent=user?user.email?.split('@')[0]||'Learner':'Guest learner';$('#avatar').textContent=user?.email?.charAt(0).toUpperCase()||'G';state.premium=false;state.expiry=null;state.attempts=backendConfigured?{}:demoProgress;if(user){const {data}=await state.supabase.from('nammath_entitlements').select('expires_at,status').eq('user_id',user.id).eq('status','active').lte('starts_at',new Date().toISOString()).gt('expires_at',new Date().toISOString()).order('expires_at',{ascending:false}).limit(1);if(data?.length){state.premium=true;state.expiry=data[0].expires_at;}const {data:progress}=await state.supabase.from('nammath_progress').select('question_id,attempts,last_correct,updated_at').eq('user_id',user.id);if(progress?.length){state.attempts=Object.fromEntries(progress.map(p=>[p.question_id,{attempts:p.attempts,correct:p.last_correct,updated:p.updated_at}]));}}else{state.attempts=backendConfigured?{}:demoProgress;}}
async function initAuth(){if(!backendConfigured)return;try {const mod=await import('https://esm.sh/@supabase/supabase-js@2.118.0');state.supabase=mod.createClient(CONFIG.supabaseUrl,CONFIG.publishableKey);await syncUser();state.supabase.auth.onAuthStateChange((event)=>{setTimeout(async()=>{if(event==='PASSWORD_RECOVERY')await promptNewPassword();await syncUser();render()},0)});await loadContent();render();}catch(e){console.error(e);toast('Unable to connect to the live backend. Running as a preview.')}}
function subscribe(){if(state.premium){toast('Your premium access is already active.');return;}modal('N$30 Premium Access',`<p>NamMath AS Premium will unlock complete worked memorandums for 30 days after a successful, server-verified payment.</p><div class="lock-box" style="margin-top:16px"><div class="lock-glyph">◇</div><h3>Payments not enabled yet</h3><p>The Namibian payment gateway must be configured and tested before subscriptions can be purchased. No charges are being collected in this preview.</p></div><button class="button-primary" data-action="close-modal">Understood</button>`)}

document.addEventListener('click',async e=>{
 const target=e.target.closest('button');if(!target)return;
 if(target.dataset.view){setView(target.dataset.view,{filter:target.dataset.filter??(target.dataset.view==='topics'?'all':state.topicFilter)});return;}
 const action=target.dataset.action;
 if(action==='close-modal'){closeModal();return}if(action==='toggle-auth'){state.authMode=state.authMode==='signin'?'signup':'signin';renderAuthModal();return}
 if(action==='password-reset'){await requestPasswordReset();return}
 if(action==='signout'){await state.supabase?.auth.signOut();closeModal();toast('Signed out.');return}
 if(action==='filter'){state.topicFilter=target.dataset.filter;render();return}
 if(action==='topic'){await startTopic(target.dataset.id);return}
 if(action==='start-exam'){await startExam(Number(target.dataset.paper));return}
 if(action==='choose'){chooseAnswer(Number(target.dataset.index));return}
 if(action==='check'){await checkAnswer();return}
 if(action==='next-question'){nextQuestion();return}
 if(action==='exit-practice'){setView(state.mode==='mock'?'papers':'topics');return}
 if(action==='view-memo'){await viewMemo();return}
 if(action==='subscribe'){subscribe();return}
 if(action==='open-resource'){await openResource(target.dataset.key,target.dataset.kind);return}
 if(action==='notes-paper'){state.notesPaper=target.dataset.paper;render();return}
 if(action==='insert-math'){insertMathSnippet(target.dataset.math);return}
 if(action==='jump-note'){const anchor=$('#note-'+CSS.escape(target.dataset.id));anchor?.scrollIntoView({behavior:'smooth',block:'start'});return}
 if(action==='show-auth'){showAuth();return}
 if(action==='restore-draft'){state.selectedNote=target.dataset.id;state.notes[state.selectedNote]={...preparedNotes[state.selectedNote]};if(!backendConfigured)writeLocal(NOTES_KEY,state.notes);render();toast('Original ChatGPT draft restored in the editor. Select Save to publish changes.');return}
});
document.addEventListener('submit',e=>{if(e.target.id==='authForm'){e.preventDefault();submitAuth(e.target)}else if(e.target.id==='newPasswordForm'){e.preventDefault();submitNewPassword(e.target)}else if(e.target.id==='resourceForm'){e.preventDefault();handleResourceUpload(e.target)}else if(e.target.id==='notesForm'){e.preventDefault();handleNoteSave(e.target)}});
document.addEventListener('change',e=>{
 if(e.target.id==='resourceCategory') {const mock=e.target.value==='mock';$('#regionField')?.classList.toggle('hidden',!mock);$('#resourceYearGroup')?.classList.toggle('hidden',mock);}
 if(e.target.id==='noteTopicSelect'){state.selectedNote=e.target.value;render();}
});
document.addEventListener('input', e => {
  if(e.target.closest('#notesForm') && e.target.matches('textarea')){refreshEditorPreview();return;}
  if(e.target.id !== 'topicSearch')return;
  state.search=e.target.value;
  const filtered=topics.filter(t=>(state.topicFilter==='all'||String(t.paper)===state.topicFilter)&&(`${t.title} ${t.tag}`.toLowerCase().includes(state.search.toLowerCase())));
  const existing=$('.topic-grid')||$('.empty');
  if(existing)existing.outerHTML=filtered.length?`<div class="topic-grid">${filtered.map(topicCard).join('')}</div>`:'<div class="empty">No topics match that search. Try a different keyword.</div>';
});
$('#authButton').addEventListener('click',showAuth);
$('#menuBtn').addEventListener('click',openMenu);
$('#scrim').addEventListener('click',closeMenu);
$('#modalRoot').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();closeModal()}});
if('serviceWorker' in navigator && (location.protocol==='https:' || location.hostname==='localhost')) navigator.serviceWorker.register('/sw.js').catch(()=>{});
$('#studioNav').classList.toggle('hidden',backendConfigured);render();initAuth();
